import json
import collections

# Parse inputs
start_x = int(input_data['start_x'])
start_y = int(input_data['start_y'])
target_x = int(input_data['target_x'])
target_y = int(input_data['target_y'])
map_id = input_data['map_id']

passable = set()

if map_id == '0_232': # Rock Tunnel B1F
    # Southern corridor (Rows 30-33, Columns 2-37)
    for y in range(30, 34):
        for x in range(2, 38):
            passable.add((x, y))

    # Remove blocked wall tiles on Row 30 (Sofia's rock wall extends down to Row 30)
    if (26, 30) in passable: passable.remove((26, 30))
    if (27, 30) in passable: passable.remove((27, 30))

    # Connection from Starting Chamber to Southern Corridor:
    # Columns 28-34 on Rows 26-29 are open
    for y in range(26, 30):
        for x in range(28, 35):
            passable.add((x, y))

    # Column 15 bypass to Western connecting corridor:
    for y in range(24, 30):
        passable.add((15, y))

    # Western connecting corridor (Rows 24-27, Columns 14-22)
    for y in range(24, 28):
        for x in range(14, 23):
            passable.add((x, y))

    # Column 20 (Western Bypass Corridor): Rows 19 to 24
    for y in range(19, 25):
        passable.add((20, y))

    # Column 25 (Western Bypass Corridor): Rows 19 to 22
    for y in range(19, 23):
        passable.add((25, y))

    # Upper bypass corridor (Rows 18-19, Columns 20-37)
    for y in (18, 19):
        for x in range(20, 38):
            passable.add((x, y))

    # Starting Chamber (Rows 22-25, Columns 28-37)
    for y in range(22, 26):
        for x in range(28, 38):
            passable.add((x, y))

    # Column 17: Rows 27 to 31
    for y in range(27, 32):
        passable.add((17, y))

elif map_id == '0_82': # Rock Tunnel 1F
    # Western Starting Area (Chamber 1)
    for y in range(2, 8):
        for x in range(14, 29):
            passable.add((x, y))
    # Column 13: Rows 2 to 7
    for y in range(2, 8):
        passable.add((13, y))
    # Eastern Corridor (Rows 10-13, Columns 20-33)
    for y in range(10, 14):
        for x in range(20, 34):
            passable.add((x, y))
    # Left corridor (Columns 2-5, Rows 7-21) on 1F
    for y in range(7, 22):
        for x in range(2, 6):
            passable.add((x, y))
    # Hiker bypass at (5, 16): remove (5, 16) from passable and route via Column 4
    if (5, 16) in passable:
        passable.remove((5, 16))
    # Eastern corridor (Columns 5-19, Rows 16-21)
    for y in range(16, 22):
        for x in range(5, 20):
            passable.add((x, y))
    # Column 16: Rows 14-15
    for y in range(14, 16):
        passable.add((16, y))
    # Column 17: Rows 11-13
    for y in range(11, 14):
        passable.add((17, y))
    # Corridor around (37, 3) (Ladder A 1F): Columns 34-37, Rows 2-13
    for y in range(2, 14):
        for x in range(34, 38):
            passable.add((x, y))

start = (start_x, start_y)
target = (target_x, target_y)

queue = collections.deque([[start]])
visited = {start}
path_found = None

while queue:
    path = queue.popleft()
    curr = path[-1]
    if curr == target:
        path_found = path
        break
    cx, cy = curr
    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nxt = (cx + dx, cy + dy)
        if nxt in passable and nxt not in visited:
            visited.add(nxt)
            queue.append(path + [nxt])

if path_found:
    buttons = []
    for i in range(len(path_found)-1):
        x1, y1 = path_found[i]
        x2, y2 = path_found[i+1]
        if x2 > x1: buttons.append('Right')
        elif x2 < x1: buttons.append('Left')
        elif y2 > y1: buttons.append('Down')
        elif y2 < y1: buttons.append('Up')
    print(json.dumps(buttons))
else:
    print(json.dumps([]))
